using System.Reflection;
using Studio.Core;
using Studio.Raple;
using TKR.Shared.resources;
using TKR.WorldServer.networking.packets.outgoing;
using TKR.WorldServer.core.objects;
using TKR.WorldServer.core.worlds;

var adapter=new RapleAdapter(Path.GetFullPath(args.FirstOrDefault()??"../raple-realms-7-server"));var checks=0;
void Check(bool value,string label){if(!value)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
void Reject(Action action,string label){try{action();}catch(Exception e)when(e is ArgumentException or InvalidOperationException){Check(true,label);return;}throw new Exception("Expected rejection: "+label);}
const string entity="Cave Pirate Brawler";
string Strike(string layout="Targets",string extra="",int core=-1)=>"new SkyStrike("+core+",StrikeLayout."+layout+",fuseMs:300,intervalMs:2000,startupMs:0,aoeRadius:1,aoeDamage:100"+(extra==""?"":","+extra)+")";
BehaviorDocument Doc(string body)=>new("class Fixture{void Build(){db.Init(\""+entity+"\",new State(\"strike\","+body+"));}}",adapter);
World World(EncounterSession session){var engine=typeof(EncounterSession).GetField("engine",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(session)!;return(World)engine.GetType().GetField("World")!.GetValue(engine)!;}
Enemy Boss(EncounterSession session)=>World(session).Enemies.Values.First(e=>e.ObjectDesc.IdName==entity);
Player Player(EncounterSession session)=>World(session).Players.Values.Single();
Check(adapter.Primitives.Single(p=>p.Name=="SkyStrike") is{Category:"Attacks",Simulatable:true},"SkyStrike exposes its original native attack constructor");
foreach(var layout in new[]{"Targets","Grid","Chain","Halo"}){var doc=Doc(Strike(layout));var pattern=adapter.ReadSkyStrike(doc,doc.AllNodes.Single(n=>n.Kind=="SkyStrike"))!;Check(pattern.Layout==layout&&RapleAdapter.SkyStrikeLayout(pattern).Count>0,"Original "+layout+" layout produces native strike origins");}
using(var native=new EncounterSession(adapter,Doc(Strike()),entity,7,new(Defense:25)))
{
    native.Advance(new(),100);Check(native.Effects.Any(e=>e.Kind==(byte)EffectType.LedgerMark&&e.DurationMs==300)&&native.Shots.Count==0,"Area strikes announce a native ring fuse without fabricating projectiles");var before=native.PlayerHp;native.Advance(new(),200);Check(native.PlayerHp==before,"Native area damage waits until the fuse is due");native.Advance(new(),100);Check(native.PlayerHp==before-75&&Player(native).HP==native.PlayerHp,"Original server area selection and defense formula reduce the visible prototype HP");Check(native.Events.Any(e=>e.Kind=="hit"&&e.Message.Contains("native server damage")),"Native server damage produces an observable hit event");
}
using(var native=new EncounterSession(adapter,Doc(Strike()),entity,7,new(Invulnerable:true))){native.Advance(new(),500);Check(native.PlayerHp==1000,"Prototype invulnerability uses the native player immunity path");}
using(var native=new EncounterSession(adapter,Doc(Strike()),entity,7,new(Spectator:true))){native.Advance(new(),500);Check(native.PlayerHp==1000,"Spectator mode preserves immunity to native area strikes");}
using(var native=new EncounterSession(adapter,Doc(Strike()),entity,7,new(Hp:30,Defense:0))){native.Advance(new(),500);Check(native.Dead&&native.PlayerHp==0&&Player(native).Dead,"Lethal native area damage reports prototype death and removes the actor from live target tracking without DB teardown");}
using(var native=new EncounterSession(adapter,Doc(Strike(extra:"aoeEffect:ConditionEffectIndex.Slowed,aoeEffectMs:500")),entity,7,new(Invulnerable:true))){native.Advance(new(),400);Check(Player(native).HasConditionEffect(ConditionEffectIndex.Slowed),"Native strike conditions still apply to invulnerable players according to the original effect guard");}
using(var native=new EncounterSession(adapter,Doc(Strike()),entity,7,new())){native.Advance(new(),100);Player(native).Move(74.5f,64.5f);native.Advance(new(),300);Check(native.PlayerHp==1000,"Area damage samples current player position at impact rather than warning position");}
using(var native=new EncounterSession(adapter,Doc(Strike()),entity,7,new())){native.Advance(new(),100);Boss(native).ApplyConditionEffect(new ConditionEffect(ConditionEffectIndex.Stunned,-1));native.Advance(new(),300);Check(native.PlayerHp==925,"Stun suppresses later volleys but does not cancel an already armed native strike");}
using(var native=new EncounterSession(adapter,Doc(Strike(extra:"totalCap:2,extra:8")),entity,7,new(Invulnerable:true))){native.Advance(new(),100);Check(native.Effects.Count(e=>e.Kind==(byte)EffectType.LedgerMark&&e.DurationMs>0)==2,"Native pending-mark caps retain only the accepted opening points");}
using(var native=new EncounterSession(adapter,Doc(Strike()),entity,7,new())){native.Advance(new(),100);var world=World(native);world.GetType().GetMethod("ClearHostileProjectiles",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(world,[Player(native)]);native.Advance(new(),400);Check(native.PlayerHp==1000&&native.Effects.Any(e=>e.Kind==(byte)EffectType.LedgerMark&&e.DurationMs==0),"Original projectile clearing cancels pending strike marks before impact");}
var phaseSource="class Fixture{void Build(){db.Init(\""+entity+"\",new State(new State(\"strike\","+Strike()+",new TimedTransition(200,\"done\")),new State(\"done\")));}}";
using(var native=new EncounterSession(adapter,new BehaviorDocument(phaseSource,adapter),entity,7,new())){native.Advance(new(),500);Check(native.PlayerHp==1000&&native.Effects.Any(e=>e.Kind==(byte)EffectType.LedgerMark&&e.DurationMs==0),"Native phase exit clears pending marks and cancels their damage");}
using(var native=new EncounterSession(adapter,Doc(Strike()),entity,7,new())){native.Advance(new(),100);Boss(native).Move(50.5f,64.5f);native.Advance(new(),300);Check(native.PlayerHp==1000,"Impact retains the native live-host fourteen-tile visibility envelope");}
var projectileStrike=Strike("Halo","count:8,gapSlots:3,shardCount:4",0).Replace("aoeRadius:1,aoeDamage:100","aoeRadius:0,aoeDamage:0");
using(var native=new EncounterSession(adapter,Doc(projectileStrike),entity,7,new(Invulnerable:true))){native.Advance(new(),400);Check(native.Shots.Count(s=>s.Count==1)==5&&native.Shots.Count(s=>s.Count==4)==5&&native.Shots.All(s=>s.Index==0),"Actual XML core and shrapnel packets resolve every accepted halo origin");Check(native.Shots.Where(s=>s.Count==1).All(s=>Math.Abs(Math.Sqrt(Math.Pow(s.X-64.5,2)+Math.Pow(s.Y-64.5,2))-4)<.0001),"XML projectile impacts preserve the original halo circle positions");}
var chainDoc=Doc(Strike("Chain","count:8,spacing:2,maxRange:10"));var chain=RapleAdapter.SkyStrikeLayout(adapter.ReadSkyStrike(chainDoc,chainDoc.AllNodes.Single(n=>n.Kind=="SkyStrike"))!);Check(chain.Count==5&&chain.Last().X==10&&chain.Last().DelayMs==480,"Native chain continues along target bearing to its configured range with exact step delays");
foreach(var layout in new[]{"Grid","Chain"})
{
    var document=Doc(Strike(layout));var pattern=adapter.ReadSkyStrike(document,document.AllNodes.Single(n=>n.Kind=="SkyStrike"))!;var expected=RapleAdapter.SkyStrikeLayout(pattern);
    using var native=new EncounterSession(adapter,document,entity,7,new(Invulnerable:true));native.Advance(new(),100);var marks=native.Effects.Where(e=>e.Kind==(byte)EffectType.LedgerMark&&e.DurationMs>0).ToArray();Check(marks.Length==expected.Count&&marks.Zip(expected).All(pair=>Math.Abs(pair.First.X-64.5-pair.Second.X)<.0001&&Math.Abs(pair.First.Y-64.5-pair.Second.Y)<.0001),"Native "+layout+" warning packets match every original pure-layout point");Check(marks.Zip(expected).All(pair=>pair.First.DurationMs==300+pair.Second.DelayMs),"Native "+layout+" fuse packets retain exact row/point staggering");
}
var original=Doc(Strike());var node=original.AllNodes.Single(n=>n.Kind=="SkyStrike");var ids=original.Identities;adapter.SetSkyStrikeLayout(original,entity,node.Id,original.Revision,"Chain");Check(adapter.ReadSkyStrike(original,original.Find(node.Id))!.Layout=="Chain","Typed layout edits preserve the native enum expression");var revision=original.Revision;original.LockedNodes.Add(node.Id);Reject(()=>adapter.SetSkyStrikeLayout(original,entity,node.Id,revision,"Halo"),"Strike region locks protect layout edits");original.LockedNodes.Clear();Reject(()=>adapter.SetSkyStrikeLayout(original,entity,node.Id,revision-1,"Halo"),"Stale strike proposals reject atomically");Check(original.Undo()&&original.Identities.SequenceEqual(ids),"Strike layout history restores source identities");
Check(adapter.Validate(Doc(Strike(extra:"count:49")),entity).Any(d=>d.IsError)&&adapter.Validate(Doc(Strike("Halo","count:4,gapSlots:3")),entity).Any(d=>d.IsError),"Original constructor count and halo-gap limits reject before playback");
var file=adapter.Catalog().Single(e=>e.Id==entity).SourceFile;var supplied=File.ReadAllText(file);var source="using TKR.WorldServer.logic.behaviors;namespace TKR.WorldServer.logic{public partial class BehaviorDb{private _ StudioSky=()=>Behav().Init(\""+entity+"\",new State(\"strike\","+Strike()+"));}}";var project=new StudioProject{SourceFile=file,Source=source,EntityId=entity,Player=new(Defense:25),Seed=7};using var literal=new EncounterSession(adapter,Doc(Strike()),entity,7,project.Player);await using var compiled=await CompiledRuntime.StartAsync(adapter.ServerRoot,project);compiled.Recording=new(compiled);literal.Advance(new(),500);await compiled.AdvanceAsync(new(),500);Check(compiled.PlayerHp==literal.PlayerHp&&compiled.Effects.SequenceEqual(literal.Effects),"Literal and compiled strike warnings, native area damage and impact effects agree");var tape=EncounterReplay.Capture(project,null,EncounterReplay.Identify(adapter,project,compiled.Stamp.BuildId),compiled);var cursor=await ReplayCursor.RestoreAsync(adapter,tape,200);using(cursor.Session){Check(cursor.Session.PlayerHp==1000,"Strike replay seek retains the pre-impact native HP");await cursor.AdvanceToAsync(500);Check(cursor.Session.PlayerHp==925&&cursor.Session.Effects.SequenceEqual(compiled.Effects),"Replay continuation reproduces native area damage and complete cue packets");}
Check(File.ReadAllText(file)==supplied,"Strike authoring and execution leave supplied source unchanged");Console.WriteLine($"{checks} native sky-strike checks passed.");
